"""Nonhomogeneous constant-coefficient first-order equations."""
def make_unit(page,ex,summary):
 return ('Hliðraðar deildajöfnur',[
 page('Þegar hægri hliðin er ekki núll','Greina hliðraða jöfnu frá óhliðraðri og athuga gefna lausn.',r'''<p>Í einingu 10 leystum við y′+ay=0. Nú bætist við gefið fall hægra megin:</p>\[y'+ay=f(x).\]<p>Hér er a enn fasti. Jafnan er <strong>hliðruð</strong> þegar f er ekki núllfallið. Fallið f er gefið; y er óþekkta fallið.</p><h2>Stöðug viðbót hægra megin</h2><h3>Sýnidæmi 11.1.1</h3>\[y'+2y=6.\]<p>Prófum fastafallið y=3. Afleiðan er núll, svo:</p>\[y'+2y=0+2\cdot3=6.\]<p>Það er lausn. Athugum nú annað fall:</p>\[y=3+4e^{-2x}.\]\[y'=-8e^{-2x}.\]\[y'+2y=-8e^{-2x}+6+8e^{-2x}=6.\]<p>Það er líka lausn. Vísisliðurinn fellur út þegar y′ og 2y eru lögð saman; fastinn 3 gefur viðbótina 6.</p><aside>Athugun fer fram í upphaflegu jöfnunni. Það nægir ekki að vísisliðurinn einn uppfylli óhliðruðu jöfnuna.</aside>''',[
 ex(r'Hvor jafnan er hliðruð: \(y\prime+3y=0\) eða \(y\prime+3y=9\)?','Skoðaðu hægri hliðina.','Hliðruð jafna hefur hægri hlið sem er ekki núllfallið.','Seinni jafnan er hliðruð. Sú fyrri er óhliðruð.','#s1'),
 ex(r'Athugaðu hvort \(y=2+5e^{-x}\) leysi \(y\prime+y=2\).','Diffraðu og settu bæði y′ og y inn.',r'\(y\prime=-5e^{-x}\).',r'Já. \(y\prime+y=-5e^{-x}+2+5e^{-x}=2\).','#s1'),
 ex(r'Finndu fastafall sem leysir \(y\prime+4y=12\).','Afleiða fastafalls er núll.','Leystu 4y=12.','Fastafallið y=3 er lausn.','#s1')]),
 page('Tiltekin lausn og almenna lausnin','Byggja almenna lausn úr einni lausn hliðruðu jöfnunnar og lausn óhliðruðu jöfnunnar.',r'''<p>Lausnin í síðasta dæmi var summa fasta og vísisliðs. Sama hugmynd gildir almennt.</p><p>Látum yₚ vera <strong>eina tiltekna lausn hliðruðu jöfnunnar</strong>. Hún þarf ekki að innihalda frjálsan fasta. Bætum við almennu lausn samsvarandi óhliðraðrar jöfnu:</p>\[y_h=Ce^{-ax}.\]<p>Þá er almenna lausn hliðruðu jöfnunnar:</p><div class="formula">\[y=y_p+Ce^{-ax}.\]</div><h2>Hvers vegna má leggja lausnirnar svona saman?</h2>\[(y_p+y_h)'+a(y_p+y_h)=(y_p'+ay_p)+(y_h'+ay_h)=f(x)+0.\]<p>Tiltekna lausnin gefur réttu hægri hliðina. Óhliðraði hlutinn gefur núll og breytir því ekki jöfnunni. Ef við drögum yₚ frá einhverri annarri lausn fæst lausn óhliðruðu jöfnunnar. Þess vegna nær þetta form yfir allar lausnir.</p><h3>Sýnidæmi 11.2.1</h3>\[y'+2y=6.\]<p>Við vitum að yₚ=3 er lausn. Samsvarandi óhliðruð jafna er y′+2y=0. Því fæst:</p>\[y=3+Ce^{-2x}.\]<p>Ef y(0)=7, þá:</p>\[7=3+C.\]\[C=4.\]\[y=3+4e^{-2x}.\]<p>Þetta er lausnin sem var athuguð í 11.1 og y(0)=7.</p><aside>Hér merkir „tiltekin lausn“ yₚ eina lausn sem hjálpar við að smíða almennu lausnina. Þegar upphafsskilyrði er síðan notað fæst ein ákveðin lausn fyrir það skilyrði.</aside>''',[
 ex(r'Gefið er að \(y_p=x\) leysi \(y\prime+y=x+1\). Finndu almennu lausnina.','Bættu við almennu lausn y′+y=0.',r'Óhliðraði hlutinn er \(Ce^{-x}\).',r'\(y=x+Ce^{-x}\). Þá er y′+y=1+x.','#s2'),
 ex(r'Leystu \(y\prime+2y=8\), með \(y(0)=1\).','Finndu fyrst fastalausn og bættu við vísislið.','Fastalausnin er yₚ=4. Notaðu 1=4+C.',r'\(y=4-3e^{-2x}\). Þá er y′+2y=8 og y(0)=1.','#s2'),
 ex(r'Er \(y=Ce^{-2x}\) eitt og sér almenn lausn \(y\prime+2y=6\)?','Settu lausnarformið inn í vinstri hliðina.','Vísisliðirnir eyða hvor öðrum.','Nei. Vinstri hliðin verður núll en á að vera 6. Til dæmis þarf að bæta fastalausninni yₚ=3 við.','#s2')]),
 page('Að finna tiltekna lausn','Prófa einfalt lausnarform og ákvarða stuðla með innsetningu.',r'''<p>Þegar hægri hliðin er einföld má oft finna yₚ með því að prófa fall af svipaðri gerð. Við <strong>setjum tilgátuna inn í jöfnuna</strong> og finnum stuðlana. Þessi leið er kölluð aðferð óákveðinna stuðla.</p><h2>Fasti hægra megin</h2><p>Fyrir y′+ay=b, þar sem a≠0, prófum við yₚ=B. Þá er:</p>\[aB=b.\]\[y_p=\frac ba.\]<h2>Línulegt fall hægra megin</h2><h3>Sýnidæmi 11.3.1</h3>\[y'+2y=4x.\]<p>Prófum yₚ=Ax+B. Afleiðan er A:</p>\[A+2(Ax+B)=4x.\]\[2Ax+(A+2B)=4x.\]<p>Stuðlarnir við x þurfa að vera jafnir og fastaliðurinn þarf að vera núll:</p>\[2A=4.\]\[A+2B=0.\]\[A=2.\]\[B=-1.\]<p>Því er yₚ=2x−1 og almenna lausnin:</p>\[y=2x-1+Ce^{-2x}.\]<p>Athugun gefur y′+2y=2−2Ce⁻²ˣ+4x−2+2Ce⁻²ˣ=4x.</p><h2>Vísisfall hægra megin</h2><h3>Sýnidæmi 11.3.2</h3>\[y'+y=3e^{2x}.\]<p>Prófum yₚ=Ae²ˣ:</p>\[2Ae^{2x}+Ae^{2x}=3e^{2x}.\]\[3A=3.\]\[A=1.\]<p>Almenna lausnin er því:</p>\[y=e^{2x}+Ce^{-x}.\]<p>Diffrun og innsetning gefa y′+y=3e²ˣ.</p><aside>Tilgátan virkar ekki alltaf óbreytt. Ef við prófum Ae⁻ˣ í y′+y=e⁻ˣ fellur vinstri hliðin út. Þá þarf annað lausnarform eða aðra leið. Í næsta undirkafla leysum við einmitt þá jöfnu með heildunarþætti. Ef a=0 er jafnan einfaldlega y′=f(x) og bein heildun nægir.</aside>''',[
 ex(r'Finndu almenna lausn \(y\prime+3y=12\).','Prófaðu fastalausn yₚ=B.','3B=12 gefur B=4.',r'\(y=4+Ce^{-3x}\). Innsetning gefur y′+3y=12.','#s3'),
 ex(r'Finndu almenna lausn \(y\prime+y=2x\).','Prófaðu yₚ=Ax+B.','Innsetning gefur Ax+(A+B)=2x, svo A=2 og B=−2.',r'\(y=2x-2+Ce^{-x}\). Þá er y′+y=2x.','#s3'),
 ex(r'Finndu almenna lausn \(y\prime+2y=4e^x\).','Prófaðu yₚ=Aeˣ.','Afleiðan er líka Aeˣ, svo 3A=4.',r'\(y=\frac43e^x+Ce^{-2x}\). Innsetning gefur y′+2y=4eˣ.','#s3')]),
 page('Heildunarþáttur','Nota margfeldisreglu til að breyta jöfnunni í heildanlega afleiðu.',r'''<p>Heildunarþáttur gefur skipulega leið þegar erfitt er að finna tiltekna lausn. Hér höldum við okkur við fastan stuðul a.</p>\[y'+ay=f(x).\]<p>Margföldum alla jöfnuna með <strong>heildunarþættinum</strong> eᵃˣ:</p>\[e^{ax}y'+ae^{ax}y=e^{ax}f(x).\]<p>Margfeldisreglan segir að vinstri hliðin sé afleiða eᵃˣy:</p>\[(e^{ax}y)'=e^{ax}f(x).\]<p>Þá heildum við hægri hliðina til að finna margfeldið eᵃˣy og deilum að lokum með eᵃˣ til að einangra y. Sýnidæmið sýnir þessi skref.</p><h3>Sýnidæmi 11.4.1</h3>\[y'+y=e^{-x}.\]<p>Hér er a=1. Margföldum með eˣ:</p>\[e^xy'+e^xy=1.\]\[(e^xy)'=1.\]<p>Heildum:</p>\[e^xy=x+C.\]<p>Deilum með eˣ:</p>\[y=(x+C)e^{-x}.\]<p>Athugum lausnina með margfeldisreglunni:</p>\[y'=e^{-x}-(x+C)e^{-x}.\]\[y'+y=e^{-x}.\]<p>Ef y(0)=2 fæst C=2 og því y=(x+2)e⁻ˣ.</p><aside>Heildunarþátturinn eᵃˣ er aldrei núll, svo margföldun og deiling með honum eru gild. Fyrst þarf að gera stuðulinn við y′ að 1. Við notum þessa aðferð í fáum einföldum dæmum; ekki þarf að læra sérstakar útgáfur fyrir breytilegan stuðul a hér.</aside>''',[
 ex(r'Leystu \(y\prime+2y=e^{-2x}\) með heildunarþætti.','Margfaldaðu með e²ˣ.','Þá fæst (e²ˣy)′=1. Heilda og einangra y.',r'\(e^{2x}y=x+C\), svo \(y=(x+C)e^{-2x}\). Diffrun gefur y′+2y=e⁻²ˣ.','#s4')]),
 page('Jafnvægi og hagnýting','Túlka fastalausn og frávik frá henni.',r'''<p>Fyrir fastar stærðir a og b, með a≠0, er almenna lausn y′+ay=b:</p>\[y=\frac ba+Ce^{-ax}.\]<p>Fastalausnin b/a er jafnvægislausn. Þegar a&gt;0 stefnir vísisliðurinn á núll og lausnin nálgast jafnvægið.</p><h2>Lausnir sitt hvorum megin við jafnvægi</h2><p>Grafið sýnir lausnir y′+y=3. Breyttu upphafsgildinu y(0). Brotna línan sýnir jafnvægislausnina y=3.</p><div class="formula" id="forced-widget"><svg id="forced-graph" viewBox="0 0 420 440" style="max-width:420px;display:block;margin:16px auto" role="img" aria-label="Lausnir y′+y=3"></svg><label for="forced-start"><strong>Upphafsgildi y(0): <output id="forced-value">1</output></strong></label><input id="forced-start" type="range" min="0" max="6" step="0.5" value="1" style="display:block;width:100%;margin:20px 0;accent-color:var(--accent)"><p id="forced-equation"></p><p id="forced-status" role="status"></p></div><h3>Sýnidæmi 11.5.1 — kæling</h3><p>Hlutur er í herbergi við stöðugan hita 20 °C. Í einföldu kælingarlíkani er breytingahraði hitastigs í hlutfalli við hitamuninn. T(t) er hitastigið í °C og t tími í mínútum:</p>\[T'=-0{,}1(T-20).\]\[T(0)=80.\]<p>Umritum:</p>\[T'+0{,}1T=2.\]<p>Fastalausnin er Tₚ=20. Almenna lausnin og upphafsskilyrðið gefa:</p>\[T=20+Ce^{-0{,}1t}.\]\[80=20+C.\]\[T(t)=20+60e^{-0{,}1t}.\]<p>Eftir 10 mínútur er hitastigið:</p>\[T(10)=20+60e^{-1}\approx42{,}1\,{}^\circ\mathrm C.\]<p>Athugun gefur \(T\prime=-6e^{-0{,}1t}=-0{,}1(T-20)\) og T(0)=80. Samkvæmt líkaninu nálgast hitastigið 20 °C ofan frá.</p>''',[
 ex(r'Finndu jafnvægislausn \(y\prime+2y=10\).','Jafnvægislausn er fastalausn.','Settu y′=0.',r'y=5 er jafnvægislausn, því 0+2·5=10.','#s5'),
 ex(r'Lausnin er \(y=5-3e^{-2x}\). Hvert stefnir y þegar x vex, og nálgast hún það gildi ofan eða neðan frá?','Vísisliðurinn stefnir á núll.','Liðurinn −3e⁻²ˣ er alltaf neikvæður.',r'Lausnin nálgast 5 neðan frá. Hún hækkar, því y′=6e⁻²ˣ>0.','#s5'),
 ex(r'Hlutur fylgir sama kælingarlíkani og í sýnidæminu, en \(T(0)=50\). Finndu T(t).','Jafnvægishitinn og stuðullinn haldast.',r'\(T=20+Ce^{-0{,}1t}\). Settu t=0 og T=50 inn.',r'\(T(t)=20+30e^{-0{,}1t}\). Þá er T′=−0,1(T−20) og T(0)=50.','#s5')]),
 page('Samantekt, orðalisti og formúlur','Tengja tiltekna lausn, óhliðraðan hluta og heildunarþátt.',summary([
 'Hliðruð jafna hefur gefna hægri hlið sem er ekki núllfallið.','Ein lausn yₚ hliðruðu jöfnunnar ásamt almennu lausn óhliðruðu jöfnunnar gefur allar lausnir.','Fyrir einfaldar hægri hliðar má prófa fastafall, línulegt fall eða vísisfall og ákvarða stuðla.','Heildunarþáttur breytir vinstri hlið í afleiðu margfeldis.','Upphafsskilyrði er sett inn eftir að almenna lausnin hefur verið fundin.','Athuga þarf lausnina í upphaflegu jöfnunni og í upphafsskilyrðinu.'
 ],[
 ('<a href="#s1">Hliðruð deildajafna</a> <span lang="en">(nonhomogeneous differential equation)</span>','Hér: jafna y′+ay=f(x) þar sem f er ekki núllfallið og a er fasti.'),
 ('<a href="#s2">Tiltekin lausn yₚ</a> <span lang="en">(particular solution)</span>','Ein lausn hliðruðu jöfnunnar sem notuð er við að smíða almennu lausnina.'),
 ('<a href="#s2">Óhliðraður hluti</a> <span lang="en">(homogeneous part)</span>','Lausn samsvarandi jöfnu y′+ay=0.'),
 ('<a href="#s3">Aðferð óákveðinna stuðla</a> <span lang="en">(method of undetermined coefficients)</span>','Lausnarform er prófað og stuðlar þess fundnir með innsetningu.'),
 ('<a href="#s4">Heildunarþáttur</a> <span lang="en">(integrating factor)</span>','Þáttur sem breytir vinstri hlið jöfnunnar í afleiðu margfeldis.'),
 ('<a href="#s5">Jafnvægislausn</a> <span lang="en">(equilibrium solution)</span>','Fastalausn deildajöfnunnar.')
 ],r'''<p><strong>Tiltekin lausn og óhliðraður hluti</strong></p>\[y'+ay=f(x).\]\[y=y_p+Ce^{-ax}.\]<p>Hér uppfyllir yₚ jöfnuna og a er fasti.</p><p><strong>Föst hægri hlið</strong></p>\[y'+ay=b.\]\[y=\frac ba+Ce^{-ax}.\]<p>Hér eru a og b fastar og a≠0. Ef a=0 nægir bein heildun.</p><p><strong>Heildunarþáttur fyrir fastan stuðul</strong></p>\[\mu(x)=e^{ax}.\]\[(e^{ax}y)'=e^{ax}f(x).\]\[y=e^{-ax}\bigl(F(x)+C\bigr).\]<p>Hér er F eitt stofnfall eᵃˣf(x). Gerum ráð fyrir samfelldu f á bilinu sem við skoðum og stuðlinum 1 við y′.</p>''')+r'''<h2>Algeng mistök</h2><ul><li>Að nota aðeins lausn óhliðruðu jöfnunnar þótt hægri hliðin sé ekki núll.</li><li>Að gleyma fastalið þegar prófað er línulegt fall Ax+B.</li><li>Að margfalda aðeins hluta jöfnunnar með heildunarþætti.</li><li>Að nota upphafsskilyrði áður en tiltekna lausnin hefur verið tekin með.</li></ul><h2>Athugaðu skilninginn</h2><ul><li>Geturðu útskýrt hvers vegna bæta má Ce⁻ᵃˣ við yₚ?</li><li>Geturðu sannreynt tilgátu um yₚ með innsetningu?</li><li>Geturðu þekkt afleiðu margfeldis eftir margföldun með heildunarþætti?</li></ul>'''),
 page('Blandað dæmasafn','Velja leið, nota upphafsskilyrði og athuga lausnir.','',[
 ex(r'Leystu \(y\prime+3y=6\), með \(y(0)=5\).','Finndu fastalausn og bættu við óhliðruðum hluta.','y=2+Ce⁻³ˣ og 5=2+C.',r'\(y=2+3e^{-3x}\). Þá er y′+3y=6 og y(0)=5.','#s2'),
 ex(r'Leystu \(2y\prime+4y=12\), með \(y(0)=0\).','Gerðu stuðulinn við y′ að 1.','Jafnan verður y′+2y=6.',r'\(y=3-3e^{-2x}\). Þá er 2y′+4y=12 og y(0)=0.','#s3'),
 ex(r'Leystu \(y\prime+y=2x\), með \(y(0)=1\).','Finndu tiltekna línulega lausn.','yₚ=2x−2 og almenna lausnin er y=2x−2+Ce⁻ˣ.',r'\(y=2x-2+3e^{-x}\). Þá er y′+y=2x og y(0)=1.','#s3'),
 ex(r'Leystu \(y\prime+y=e^{-x}\), með \(y(0)=3\).','Heildunarþáttur eˣ einfaldar hægri hliðina.','(eˣy)′=1 gefur eˣy=x+C.',r'\(y=(x+3)e^{-x}\). Þá er y′+y=e⁻ˣ og y(0)=3.','#s4'),
 ex(r'Nemandi telur \(y=4+Ce^{-2x}\) vera almennu lausn \(y\prime+2y=6\). Athugaðu þetta og leiðréttu ef þarf.','Reiknaðu vinstri hlið með gefna fallinu.','Vísisliðirnir falla út en 2·4 situr eftir.',r'Vinstri hlið verður 8 en á að vera 6. Rétt almennt lausnarform er \(y=3+Ce^{-2x}\).','#s2'),
 ex(r'Leystu \(y\prime+2y=4e^x\), með \(y(0)=0\).','Prófaðu tiltekna lausn Aeˣ.','A=4/3 og y=4eˣ/3+Ce⁻²ˣ.',r'\(y=\frac43(e^x-e^{-2x})\). Þá er y′+2y=4eˣ og y(0)=0.','#s3'),
 ex(r'Lausnin er \(y=7+2e^{-x}\). Finndu jöfnu á forminu y′+y=b og lýstu hegðun lausnarinnar þegar x vex.','Leggðu afleiðuna og fallið saman.','Vísisliðirnir eyða hvor öðrum.',r'Jafnan er y′+y=7. Lausnin minnkar og nálgast 7 ofan frá.','#s5')])])
